resources.string:
"#version 300 es\n"

uniform mat4 uMVPMatrix;
uniform float wave;
uniform vec2 position[256];
in vec4 vPosition;
in vec3 vNormal;
in vec2 a_TexCoordinate;
out vec2 texCoord;

void main() {


    vec4 outPos = vPosition;
    outPos.xz = outPos.xz + position[gl_InstanceID];

    outPos.x = outPos.x + sin( wave + outPos.x + outPos.y ) * 0.5 * outPos.y;
    outPos.z = outPos.z + cos( wave + outPos.x + outPos.y ) * 0.1 * outPos.y;
    outPos.y = outPos.y - sin( wave + outPos.x + outPos.y ) * 0.5 * outPos.y;

    gl_Position = uMVPMatrix * vec4(outPos.xyz, 1.0);

    texCoord = a_TexCoordinate;
}

"#version 300 es\n"

precision mediump float;

uniform sampler2D u_Texture;
in vec2 texCoord;

out vec4 gl_FragColor;

void main() {

vec4 color = texture(u_Texture, texCoord);

if(color.a<0.5){
    discard;
}

gl_FragColor = color;
}
